void uGUISkill::setupListItem(uGUIBase::cScrollListItemBase* pItemBase, uGUIBase::cScrollListInfoBase* pInfoBase, u32 index) {
    if (pItemBase == nullptr) {
        return;
    }
    if (pInfoBase == nullptr) {
        return;
    }
    cListItem* pItem = static_cast<cListItem*>(pItemBase);
    setInstanceExecuteTree(static_cast<cGUIInstance*>(pItem->mpInstNull), true);
    setInstanceVisible(static_cast<cGUIInstance*>(pItem->mpInstNull), true);
    switch (pInfoBase->mItemType) {
        case 0:
        {
            setupJobItem(static_cast<cListItem*>(pItemBase), static_cast<cListInfo*>(pInfoBase), index);
            break;
        }
        case 1:
        {
            setupNormalItem(static_cast<cListItem*>(pItemBase), static_cast<cListInfo*>(pInfoBase), index);
            break;
        }
        case 2:
        {
            setupCustomItem(static_cast<cListItem*>(pItemBase), static_cast<cListInfo*>(pInfoBase), index);
            break;
        }
        case 3:
        {
            setupAbilityItem(static_cast<cListItem*>(pItemBase), static_cast<cListInfo*>(pInfoBase), index);
            break;
        }
        default:
        {
            break;
        }
    }
}

