    if (mPawnId == mNowReqPawnId) {
        return;
    }
    setUseIGUIExtNetFunc(static_cast<sGUIExt*>(sGUI::getInstance())->requestGetPawnLearnedCustomSkill(mPawnId, true));
    setUseIGUIExtNetFunc(static_cast<sGUIExt*>(sGUI::getInstance())->requestGetPawnLearnedNormalSkill(mPawnId, true));
