__attribute__((weak)) void uGUISkill::eventAdjustCursor() {
    if (static_cast<int>(mFlowId) <= 9) {
        if (mFlowId == 5) {
            setupJobInfo();
            adjustJobCursor(false);
        }
    } else {
        switch (mFlowId - 10u) {
            case 0:
            {
                adjustCustomCursor();
                break;
            }
            case 1:
            {
                adjustCustomCursor();
                break;
            }
            case 5:
            {
                adjustNormalCursor();
                break;
            }
            case 8:
            {
                setupAbilitySetList();
                adjustAbilityCursor();
                break;
            }
            case 9:
            {
                setupAbilitySetList();
                adjustAbilityCursor();
                break;
            }
            case 13:
            {
                adjustSearchCursor();
                break;
            }
            case 16:
            {
                setupPresetList();
                setupPresetSetList();
                if (mpPresetCtrl != nullptr) {
                    mPresetL.mCursor.setCtrlPos(mpPresetCtrl->getCurrentPos(), false);
                } else {
                    mPresetL.mCursor.setCtrlPos(0, false);
                }
                break;
            }
            case 18:
            {
                adjustRenameCursor();
                break;
            }
            default:
            {
                break;
            }
        }
    }
}

